/* Sets the proximity query center (position relative to origin if given) and its radius and half radius. */ void setProximityQuery(s32 origin, void *position, f32 radius) {
    if (origin != 0) {
        vec3Subtract(position, origin, &gProximityQueryCenter, position);
    } else {
        *(__repair_record_copy_3 *) &gProximityQueryCenter = *(__repair_record_copy_3 *) position;
    }
    gProximityQueryRadius = radius;
    gProximityQueryHalfRadius = radius * 0.5f;
}
